/**
 * Determines whether a document location uses a safe protocol. Relative
 * locations (which cannot be parsed as absolute URLs) are considered safe,
 * while absolute URLs must use the `http:` or `https:` protocol.
 */
const isSafeLocation = (location: string): boolean => {
  let url: URL;
  try {
    url = new URL(location);
  } catch {
    // Relative locations have no protocol and are safe to return.
    return true;
  }
  return url.protocol === 'http:' || url.protocol === 'https:';
};

/**
 * Registers a search query action with the provided actions registry.
 */
export const createQueryAction = ({
  engine,
  actionsRegistry,
  searchIndexService,
  logger,
}: {
  engine: SearchEngine;
  actionsRegistry: ActionsRegistryService;
  searchIndexService: SearchIndexService;
  logger: LoggerService;
}): void => {
  const documentTypes = Object.keys(searchIndexService.getDocumentTypes());
  const typesDescription =
    documentTypes.length > 0
      ? `Available document types are: ${documentTypes.join(', ')}.`
      : 'There are currently no indexed document types.';

  actionsRegistry.register({
    name: 'search-query',
    title: 'Search Query',
    description: `
Query the Backstage search engine and return matching documents.

Each result has a \`type\` (the kind of document, e.g. "software-catalog" or "techdocs") and a
\`document\` with at least a \`title\`, \`text\`, and \`location\` (the URL of the document). ${typesDescription}

## Filtering

- \`types\` — restrict the search to specific document types.
- \`filters\` — a nested object of field/value constraints forwarded to the search engine.

## Pagination

Use \`pageLimit\` to control the number of results per page and \`pageCursor\` to fetch a specific page.
The response includes \`nextPageCursor\` and \`hasMoreResults\` to help you paginate, as well as an
optional \`totalItems\` count.
    `,
    attributes: {
      destructive: false,
      readOnly: true,
      idempotent: true,
    },
    schema: {
      input: z =>
        z.object({
          term: z
            .string()
            .describe('The free-text search term to query for.'),
          types: z
            .array(z.string())
            .optional()
            .describe(
              'Optional list of document types to restrict the search to.',
            ),
          filters: z
            .object({})
            .passthrough()
            .optional()
            .describe(
              'Optional nested object of field/value constraints forwarded to the search engine.',
            ),
          pageLimit: z
            .number()
            .optional()
            .describe('Maximum number of results to return per page.'),
          pageCursor: z
            .string()
            .optional()
            .describe('Cursor identifying the page of results to return.'),
        }),
      output: z =>
        z.object({
          results: z
            .array(
              z.object({
                type: z
                  .string()
                  .describe('The type of the returned document.'),
                document: z
                  .object({
                    title: z.string(),
                    text: z.string(),
                    location: z.string(),
                  })
                  .passthrough()
                  .describe('The matched document.'),
              }),
            )
            .describe('List of documents matching the query.'),
          nextPageCursor: z
            .string()
            .optional()
            .describe('Cursor for retrieving the next page of results.'),
          totalItems: z
            .number()
            .optional()
            .describe('Total number of results matching the query.'),
          hasMoreResults: z
            .boolean()
            .describe('Whether there are more results to fetch.'),
        }),
    },
    action: async ({ input }) => {
      const { term, types, filters, pageLimit, pageCursor } = input;

      const response = await engine.query({
        term,
        types,
        filters,
        pageLimit,
        pageCursor,
      });

      const results = [];
      for (const result of response.results) {
        const { authorization, ...document } = result.document;

        if (!isSafeLocation(document.location)) {
          logger.info(
            `Excluding search result with unsafe location: ${document.location}`,
          );
          continue;
        }

        results.push({
          ...result,
          document,
        });
      }

      return {
        output: {
          results,
          nextPageCursor: response.nextPageCursor,
          totalItems: response.numberOfResults,
          hasMoreResults: Boolean(response.nextPageCursor),
        },
      };
    },
  });
};
